    Host-Guard;Invoke-Command -Session $session -ArgumentList $task,$stage,$wrapperPin -ScriptBlock {param($Task,$Stage,$Pin);$ErrorActionPreference='Stop';$t=Get-ScheduledTask -TaskName $Task;$i=Get-ScheduledTaskInfo -TaskName $Task;if($t.State.ToString() -cne 'Ready' -or $i.LastRunTime.Year -ge 2000 -or (Get-FileHash -LiteralPath (Join-Path $Stage 'wrapper.ps1')).Hash.ToLowerInvariant() -cne $Pin -or @(Get-ScheduledTask|Where-Object {$_.TaskName -like 'N2R-*' -and $_.State.ToString() -in @('Running','Queued')}).Count){throw 'Only the untouched fresh task may start once.'};Start-ScheduledTask -TaskName $Task};Save 'start.json' @{start_issued_once=$true;utc=[DateTime]::UtcNow.ToString('o')};Get-Content -LiteralPath (Join-Path $root 'dispatch.json') -Raw
}catch{Save 'dispatch-failed.json' @{success=$false;run_id=$run;error=$_.Exception.ToString();automatic_retry=$false;native_worker_termination_inferred=$false;utc=[DateTime]::UtcNow.ToString('o')};throw}
finally{if($null -ne $session){Remove-PSSession $session}}
